def fields_to_hide(self):
    return ["skus", "warehouse_ids"]

def statuses(self):
    return [
        "open",
        "confirmed",
        "processing",
        "partially_fulfilled",
        "fulfilled",
        "exception",
        "cancelled",
        "backordered",
        "other",
    ]

def validate(self, order):
    validate_created_updated(order)
    find_duplicates(order["line_items"], "line_item_id")
    find_duplicates(order["shipping_groups"], "shipping_group_id")
    find_duplicates(order["shipments"], "shipment_id")
    li_product_id_to_quantity = defaultdict(int)
    for line_item in order["line_items"]:
        product_id = line_item["product_id"]
        li_product_id_to_quantity[product_id] += line_item["quantity"]
    shipment_variant_to_quantity = defaultdict(int)
    if order["shipping_groups"]:
        if self.integration.integration_name != "shopify":
            raise Exception("Shipping groups should not be present if not Shopify")
        for shipping_group in order["shipping_groups"]:
            find_duplicates(shipping_group["line_items"], "line_item_id")
    for shipment in order["shipments"]:
        find_duplicates(shipment["line_items"], "shipment_line_item_id")
        if shipment["status"] == "cancelled":
            continue
        for product in shipment["line_items"]:
            product_id = product["product_id"]
            shipment_variant_to_quantity[product_id] += product["quantity"]
            product_id = product["product_id"]
    if self.integration.validate_shipment_lis_in_lis():
        for product_id, quantity in shipment_variant_to_quantity.items():
            li_quantity = li_product_id_to_quantity[product_id]
            if order["status"] == "fulfilled":
                # assert (
                #     quantity == li_quantity
                # ), f"Shipment quantity {quantity} does not match line item quantity {li_quantity} for variant {product_id}"
                pass
                # removing this for now because we're listing refunded/unfulfillable items in the top level line items response
            else:
                assert quantity <= li_quantity, (
                    f"Shipment quantity {quantity} exceeds line item quantity {li_quantity} for variant {product_id}"
                )

